// spec: .qa/e2e/specs/journey.md
// seed: tests/seed.user1.spec.ts
// Только чтение. «Новое устройство / другой браузер / после очистки данных сайта» = новый контекст с сессией user1
// без ключа localStorage['journey']. Окно уровня НЕ подавляется (suppressMilestoneWindow не вызывается) — это и проверяем.
// Прогоны: Chrome 1440 (desktop), Safari/WebKit iPhone 13 Mini, Chrome Pixel 7 — три разных «устройства».
import { test, expect, Page } from '@playwright/test';
import { openWithoutJourneyKey, expectNoMilestoneWindow } from '../_helpers/milestone';

async function openJourney(page: Page, how: 'goto' | 'reload') {
  if (how === 'reload') await page.reload();
  else await page.goto('/journey');
  await expect(page.getByRole('heading', { level: 1, name: 'המסע שלי' })).toBeVisible({ timeout: 20_000 });
  // предусловие: user1 уже на уровне 10 — повышения быть не может
  await expect(page.getByText('דרגה 10 מתוך 10')).toBeVisible({ timeout: 20_000 });
}

test.describe('«המסע שלי»', () => {
  test('JR-06 Окно «עלית דרגה» не показывается на новом устройстве без повышения (user1, уровень 10, без ключа journey) #22c9d541 @prod-safe', async ({ browser }, testInfo) => {
    const { page, close } = await openWithoutJourneyKey(browser, testInfo, 'user1');
    try {
      // Признак показанного уровня читается из аккаунта (user_profiles.last_announced_rung).
      const announced: number[] = [];
      page.on('response', async (r) => {
        if (!r.url().includes('/rest/v1/user_profiles') || r.request().method() !== 'GET') return;
        const body = await r.text().catch(() => '');
        for (const m of body.matchAll(/"last_announced_rung"\s*:\s*(\d+)/g)) announced.push(Number(m[1]));
      });

      await test.step('1. Первое открытие /journey — окна нет', async () => {
        await openJourney(page, 'goto');
        // источник: «מה רצוי» — הסימון נשמר בחשבון… כניסה ממכשיר אחר, מדפדפן אחר או אחרי ניקוי נתונים אינה מציגה אותו שוב
        await expectNoMilestoneWindow(page);
      });

      await test.step('2. Аккаунт: last_announced_rung = 10 (не ниже текущего уровня)', async () => {
        // источник: комментарий программиста 4.10 — миграция 20261004160000 пометила всех текущим уровнем
        await expect.poll(() => announced.length, { timeout: 15_000, message: 'нет last_announced_rung в ответе user_profiles' }).toBeGreaterThan(0);
        expect(Math.max(...announced)).toBeGreaterThanOrEqual(10);
      });

      await test.step('3. Перезагрузка — окна нет', async () => {
        await openJourney(page, 'reload');
        await expectNoMilestoneWindow(page);
      });

      await test.step('4. Уход на /home и обратно на «המסע שלי» — окна нет', async () => {
        await page.goto('/home');
        await expect(page.getByText('תזכורות מהירות', { exact: true })).toBeVisible({ timeout: 20_000 });
        await openJourney(page, 'goto');
        await expectNoMilestoneWindow(page);
      });

      await test.step('5. Экран не перекрыт — «צפה בהכל» открывает историю', async () => {
        // источник: «מה קיים» — החלון מסתיר את המסך עד שסוגרים אותו (больше не должно)
        await page.getByRole('link', { name: 'צפה בהכל' }).click();
        await expect(page).toHaveURL(/\/journey\/history/);
      });
    } finally {
      await close();
    }
  });
});
